490		}
491		if rep.Results[3].Status != "missing_in_ledger" {
492			t.Fatalf("rX status=%s", rep.Results[3].Status)
493		}
494		// p2 重复组抑制缺失；p1 已覆盖（字段不符也算覆盖）。账本无退款 -> 无缺失退款。
